input.command:
export PGDATABASE=etl_scratch && cat > /tmp/naive_etl.sql <<'SQL'
BEGIN;
TRUNCATE dash_revenue_by_category, dash_revenue_by_country;
INSERT INTO dash_revenue_by_category (month, category, revenue, order_count, units_sold)
SELECT to_char(o.order_date,'YYYY-MM'), COALESCE(p.category,'(no items)'), SUM(COALESCE(oi.quantity*oi.unit_price,0)), COUNT(DISTINCT o.order_id), SUM(COALESCE(oi.quantity,0))
FROM orders o LEFT JOIN order_items oi USING (order_id) LEFT JOIN products p USING (product_id)
WHERE o.status='COMPLETED' GROUP BY 1,2;
DO $x$ DECLARE s bigint; l bigint; BEGIN
SELECT COUNT(*) INTO s FROM orders WHERE status='COMPLETED';
SELECT COALESCE(SUM(order_count),0) INTO l FROM dash_revenue_by_category;
INSERT INTO etl_run_log (started_at, finished_at, source_order_count, loaded_order_count, mismatch) VALUES (now(), clock_timestamp(), s, l, s-l);
IF s-l <> 0 THEN RAISE EXCEPTION 'ETL reconciliation failed: source=% loaded=% mismatch=%', s, l, s-l; END IF;
END $x$;
COMMIT;
SQL
psql -v ON_ERROR_STOP=1 -f /tmp/naive_etl.sql; echo "naive exit=$?"; psql -At -c "select count(*) from etl_run_log"; rm -f /tmp/naive_etl.sql
psql -d postgres -c "DROP DATABASE etl_scratch"

